/* Carga CuscoExtrajudicialSetiembre -> [Analitica].[Cusco].[ExtraJudicial_Asignacion] | Periodo 202609
   Solo INSERT (no borra ni actualiza). Omite cuentas ya existentes en el periodo.
   PRUEBA por defecto (ROLLBACK). Para guardar: cambiar @Commit = 1 */
USE Analitica; SET NOCOUNT ON; SET XACT_ABORT ON;
DECLARE @Commit bit = 0;   -- 0 = prueba (revierte)  |  1 = guarda
DECLARE @Periodo varchar(6) = '202609';
BEGIN TRAN;
SELECT TOP 0 REGION,AGENCIA,Producto,Tipo,Moneda,Cuenta,Titular,Doc_Titular,Telefono,Departamento,Provincia,Distrito,Domicilio,Domicilio_Negocio,Conyuge,Doc_Conyuge,Telefono_Conyuge,Aval,Doc_Aval,Domicilio_Aval,Telefono_Aval,Saldo_Capital,Interes,Mora,Gastos,DEUDA_TOTAL,RANG_K,Anio_Transferencia,Minimo_Cobrar_Sin_Campana,Segmento_Campana,DSC_CAPITAL,Capital_DSC_Capital,Monto_Cobrar_Campana,Monto_Pago,Fecha_Ultimo_Pago,Fecha_Venta_Cartera,Proceso_Venta,Fecha_Transferencia,Demanda,Condicion,Cuotas_Pagadas,Negociado,Monto_Negociado,Cuotas_Negociadas,Estudio_Juridico_Final,Programas,Tipo_Garantia,Linea,Periodo INTO #stg FROM [Cusco].[ExtraJudicial_Asignacion];



































DECLARE @enExcel int = (SELECT COUNT(*) FROM #stg), @yaExisten int =
  (SELECT COUNT(*) FROM #stg s WHERE EXISTS (SELECT 1 FROM [Cusco].[ExtraJudicial_Asignacion] t WHERE t.Cuenta=s.Cuenta AND t.Periodo=@Periodo));
SELECT REGION,AGENCIA,Producto,Tipo,Moneda,Cuenta,Titular,Doc_Titular,Telefono,Departamento,Provincia,Distrito,Domicilio,Domicilio_Negocio,Conyuge,Doc_Conyuge,Telefono_Conyuge,Aval,Doc_Aval,Domicilio_Aval,Telefono_Aval,Saldo_Capital,Interes,Mora,Gastos,DEUDA_TOTAL,RANG_K,Anio_Transferencia,Minimo_Cobrar_Sin_Campana,Segmento_Campana,DSC_CAPITAL,Capital_DSC_Capital,Monto_Cobrar_Campana,Monto_Pago,Fecha_Ultimo_Pago,Fecha_Venta_Cartera,Proceso_Venta,Fecha_Transferencia,Demanda,Condicion,Cuotas_Pagadas,Negociado,Monto_Negociado,Cuotas_Negociadas,Estudio_Juridico_Final,Programas,Tipo_Garantia,Linea,Periodo FROM #stg s
WHERE NOT EXISTS (SELECT 1 FROM [Cusco].[ExtraJudicial_Asignacion] t WHERE t.Cuenta=s.Cuenta AND t.Periodo=@Periodo);
DECLARE @insertadas int = @@ROWCOUNT;
SELECT @enExcel AS filas_en_script, @yaExisten AS ya_existian_omitidas, @insertadas AS insertadas,
       (SELECT COUNT(*) FROM [Cusco].[ExtraJudicial_Asignacion] WHERE Periodo=@Periodo) AS total_periodo,
       (SELECT SUM(Saldo_Capital) FROM [Cusco].[ExtraJudicial_Asignacion] WHERE Periodo=@Periodo) AS saldo_capital_periodo;
-- Esperado: filas_en_script = 16767 | saldo capital del Excel = 32,104,759.17
IF @Commit = 1 BEGIN COMMIT; PRINT 'CONFIRMADO'; END ELSE BEGIN ROLLBACK; PRINT 'PRUEBA: se revirtio todo. Cambia @Commit = 1 para guardar.'; END
DROP TABLE IF EXISTS #stg;